def data(i): return get_json(f"https://www.arcgis.com/sharing/rest/content/items/{i}/data")
def walk(Ls,out):
    for L in Ls:
        if L.get("url"): out.append((L.get("title"),L["url"]))
        walk(L.get("layers",[]),out)
for eid in ["9036ab6c69d24bdaa950f1ea5bf63445"]:
    e=item(eid); print("EXP",e["title"],e["owner"])
    ids=set(re.findall(r'"itemId":\s*"([0-9a-f]{32})"',json.dumps(data(eid))))
    for i in ids:
        it=item(i)
        if it.get("type")=="Web Map":
            out=[]; walk(data(i).get("operationalLayers",[]),out)
            for t,u in out:
                try:
                    inf=get_json(u); c=get_json(u+"/query",{"where":"1=1","returnCountOnly":"true"}).get("count")
                    print("  ",t,"|",inf.get("geometryType"),"|",c,"|",u)
                except Exception as ex: print("  ",t,"ERR",str(ex)[:60])
for u in ["https://services.arcgis.com/QO7AhQX53d0m9M2s/arcgis/rest/services/Uniti_Wholesale_Map_Demo_4_WFL1/FeatureServer/26","https://services.arcgis.com/QO7AhQX53d0m9M2s/arcgis/rest/services/Uniti_Wholesale_Dark_Fiber/FeatureServer/74","https://services.arcgis.com/QO7AhQX53d0m9M2s/arcgis/rest/services/Uniti_Wholesale_Map_Demo_4_WFL1/FeatureServer/54","https://services.arcgis.com/QO7AhQX53d0m9M2s/arcgis/rest/services/Key_Strategic_Routes_731/FeatureServer/199","https://services.arcgis.com/QO7AhQX53d0m9M2s/arcgis/rest/services/Regional_Transport_Network_6_13/FeatureServer/194","https://services.arcgis.com/QO7AhQX53d0m9M2s/arcgis/rest/services/National_Core_Network_6_12/FeatureServer/191"]:
