import csv, re
from sources.arcgis import get_json
known={r["layer_url"].rsplit("/",1)[0] for r in csv.DictReader(open("sources/arcgis_fiber_catalog.csv",encoding="utf-8"))}
BOX={"New York":(-79.8,40.5,-71.8,45.1),"Connecticut":(-73.8,40.9,-71.7,42.1),"Massachusetts":(-73.6,41.2,-69.9,42.9),"New Jersey":(-75.6,38.9,-73.8,41.4)}
TERMS='(fiber OR fibre OR telecom OR "middle mile" OR conduit OR ITS OR communication OR communications OR backbone OR "dark fiber") -title:"Partnerships for the Goals"'
TOPIC=re.compile(r"fib|telecom|middle|conduit|\bits\b|communic|backbone|dark|cable",re.I)
TARGET={"Massachusetts":['MassBroadband','"MBI" middle mile','Massachusetts Broadband Institute','OpenCape','Whip City Fiber','Holyoke Gas Electric fiber','MassDOT ITS','MassDOT fiber','KCST','Axiom fiber'],
 "Connecticut":['"Connecticut Education Network"','CEN fiber','CTDOT fiber','CTDOT ITS','Connecticut fiber','Norwich fiber'],
 "New York":['NYSERNet','ION network fiber','"Empire State Development" fiber','NYSDOT fiber','NYSDOT ITS','New York fiber','NYC fiber','DoITT fiber','Hudson Valley fiber','Monroe County fiber','Onondaga fiber','Erie County fiber','Westchester fiber','Long Island fiber'],
 "New Jersey":['NJEDge','NJDOT fiber','NJDOT ITS','New Jersey fiber','NJ Transit fiber','NJTA fiber','Garden State fiber']}
seen=set()
def show(tag,it):
    if it["id"] in seen or not it.get("url"): return
    seen.add(it["id"])
    k="KNOWN" if it["url"].rstrip("/") in known else "new"
    print(f"{tag[:14]:14}|{k:5}|{it['title'][:58]:58}|{it['owner'][:26]:26}|{it['url']}")
for st,(x0,y0,x1,y1) in BOX.items():
    print("=====",st)
    for kind in ("Feature Service","Map Service"):
        start=1
        while 0<start<=1000:
            r=get_json("https://www.arcgis.com/sharing/rest/search",{"q":f'{TERMS} type:"{kind}"',"bbox":f"{x0},{y0},{x1},{y1}","num":100,"start":start})
            for it in r["results"]:
                ext=it.get("extent") or []
                if not ext: continue
                (a,b),(c,d)=ext; cx,cy=(a+c)/2,(b+d)/2
                if x0<=cx<=x1 and y0<=cy<=y1 and TOPIC.search(it["title"]+" "+" ".join(it.get("tags") or [])): show("bbox",it)
            start=r.get("nextStart",-1)
    for q in TARGET[st]:
        r=get_json("https://www.arcgis.com/sharing/rest/search",{"q":f'({q}) (type:"Feature Service" OR type:"Map Service")',"num":30})
        for it in r["results"]:
            if TOPIC.search(it["title"]+" "+" ".join(it.get("tags") or [])): show(q,it)
EOF

